# CELL 14: DATASET SUMMARY REPORT   (Eir 2.0.13)
#
# Produces a plain-language summary of a post-processed Eir run, reporting
# every headline figure twice: once over all structures, and once over only
# those whose geometry passed the plausibility screen.
#
# CHANGED IN 2.0.2: which GII to quote is now decided by the data and stated
# explicitly. On a disordered dataset the per-species GII is not a meaningful
# quantity, and reporting it as the headline overstates the instability of the
# whole family by a factor of several. See section 2.
#
# Usage:  summarise_dataset(dfq)                  # print to screen
#         summarise_dataset(dfq, save_to='...')   # also write a text file

import os
import re
import numpy as np
import pandas as pd


DIAGNOSIS_MEANING = {
    'cation_and_anion_agree':
        "cations and oxygens both balance - no evidence of a problem",
    'cation_only_deviates':
        "cations deviate but oxygens balance - points to the bond valence\n"
        "        parameters rather than the structure",
    'both_deviate':
        "cations and oxygens both deviate - a structural or data problem, or\n"
        "        genuine strain (check polyhedron_regular to tell these apart)",
    'anion_only_deviates':
        "oxygens deviate but cations balance - usually the assumed anion\n"
        "        valence is wrong",
    'both_deviate_regular':
        "both deviate and the polyhedra are regular - a structural or data\n"
        "        problem rather than strain",
    'both_deviate_distorted':
        "both deviate and at least one polyhedron is distorted - usually real,\n"
        "        e.g. a Jahn-Teller active ion, which bond valence handles poorly",
    'insufficient_data':
        "not enough information to judge",
}

# Alias of DIAGNOSIS_ORDER (CELL 7), which is where the list lives. This was
# a byte-identical second copy under a different name, so the definition in
# CELL 7 read as dead code and either could have drifted.
DIAGNOSIS_ORDER_REPORT = DIAGNOSIS_ORDER


def _fmt(value, dp=4):
    if value is None or (isinstance(value, float) and np.isnan(value)):
        return "n/a"
    return f"{value:.{dp}f}"


def _two_column(label, all_val, sub_val, dp=4, width=34):
    return f"  {label:<{width}} {_fmt(all_val, dp):>14} {_fmt(sub_val, dp):>16}"


def summarise_dataset(dfq, save_to=None, gii_threshold=0.20,
                      shift_results=None):
    """
    Summarise a post-processed Eir dataset.

    dfq : DataFrame returned by add_coordination_quality()
    """
    lines = []
    def out(s=""):
        lines.append(s)

    per = dfq.groupby('filename').first()

    # A structure is treated as sound only if it passes ALL the geometric
    # tests present in the file. They are independent: on the reference set
    # each catches structures the others miss, and none is caught by all
    # three, so taking only the first would understate the failure rate.
    # v2.0.2: five screens, not three, and read from the STRUCTURE-level
    # columns.
    #
    # 'core_geometry_plausible' in the CSV is the PER-SITE radii verdict; Eir
    # exports its structure-level counterpart separately. Taking .first() of
    # the per-site column reads whichever site happens to come first and
    # misses the failure whenever the bad site is not row one. On the
    # 934-structure ICSD perovskite set that reported 39 flagged structures
    # where the correct count is 63.
    #
    # The coordination and half-lattice screens were added in 2.0.2 and were
    # simply absent here, so 'passed every test' was measured against three
    # tests out of five and came out 91% where the true figure is 88%.
    _screens = [('radii ratio', 'structure_core_geometry_plausible'),
                ('bond-valence distance', 'structure_bvs_geometry_plausible'),
                ('anion-anion packing', 'anion_packing_plausible'),
                # v2.0.13: the cation floor, measured from the distributions
                # of all three reference families. 19 exclusive catches,
                # including two perovskites that sat in the triage's
                # UNEXPLAINED bucket.
                ('cation-cation packing', 'cation_packing_plausible'),
                ('coordination', 'structure_cn_plausible')]
    _screens = [(n, c) for n, c in _screens if c in per.columns]
    if 'core_geometry_plausible' in per.columns and             'structure_core_geometry_plausible' not in per.columns:
        # older CSV: roll the per-site column up rather than reading row one
        _roll = (dfq.assign(_c=dfq['core_geometry_plausible']
                            .astype(str).str.lower())
                    .groupby('filename')['_c']
                    .apply(lambda s: not (s == 'false').any()))
        per = per.copy()
        per['structure_core_geometry_plausible'] = per.index.map(_roll)
        _screens.insert(0, ('radii ratio', 'structure_core_geometry_plausible'))

    # The half-lattice screen reports a count, not a boolean.
    _shift_col = ('n_sites_shift_proposed'
                  if 'n_sites_shift_proposed' in per.columns else None)
    if _shift_col is not None:
        per = per.copy()
        per['_shift_ok'] = ~(pd.to_numeric(per[_shift_col], errors='coerce')
                             .fillna(0) > 0)
        _screens.append(('half-lattice shift', '_shift_ok'))
    plaus_mask = pd.Series(True, index=per.index)
    for _n, _c in _screens:
        plaus_mask &= (per[_c] != False)
    good = per[plaus_mask]
    n_all, n_good = len(per), len(good)
    n_bad = n_all - n_good

    sites_all = len(dfq)
    good_files = set(good.index)
    sites_good = int(dfq['filename'].isin(good_files).sum())

    out("=" * 78)
    out("EIR DATASET SUMMARY")
    out("=" * 78)
    out()
    out(f"  Structures analysed          {n_all}")
    out(f"  Crystallographic sites       {sites_all}")
    out()

    # ---------------------------------------------------------------- 1
    out("-" * 78)
    out("1. GEOMETRY SCREENING")
    out("-" * 78)
    out()
    out("  Bond valence is calculated from bond lengths, so a length that cannot")
    out("  be right makes every number built on it meaningless. Each structure")
    out("  is therefore tested before anything is interpreted.")
    out()
    out("  The tests are independent and look at different things:")
    out()
    out("    radii ratio            shortest cation-anion contact against the")
    out("                           sum of the Shannon ionic radii, flagged")
    out("                           below 85%")
    out("    bond-valence distance  the same contact against the distance the")
    out("                           cation's own bond valence parameters imply,")
    out("                           flagged below 90%. Needs no radii table and")
    out("                           no assumption about the cation's role.")
    out("    coordination           whether the ion is observed at this")
    out("                           coordination at all. The only test that")
    out("                           asks whether bonds are MISSING rather")
    out("                           than too short.")
    out("    half-lattice shift     whether translating the cation by half a")
    out("                           lattice vector gives a better polyhedron,")
    out("                           which suggests it was deposited on the")
    out("                           wrong origin. Detected and proposed only;")
    out("                           nothing is corrected.")
    out(f"    anion-anion packing    shortest contact between two anions. The")
    out("                           cation-centred tests look outward from a")
    out("                           cation and cannot see it. ICSD 85235 has a")
    out(f"                           GII of 0.0047 and two oxygens 2.191 A")
    out(f"                           apart. Flagged below {ANION_ANION_MIN} A.")
    out("    cation-cation packing  the same for the cation sublattice.")
    out("                           Edge- and face-sharing polyhedra reach")
    out(f"                           2.6-3.0 A and no closer; flagged below")
    out(f"                           {CATION_CATION_MIN} A, or {MONOVALENT_PAIR_MIN} A "
        f"between two")
    out("                           monovalent cations (Li3N, Li2O).")
    out()
    out("  These are the EVIDENCE. The verdict that follows from them is the")
    out("  PGRM integrity tier, reported below and carried per structure in")
    out("  structure_pgrm_tier.")
    out()
    # v2.0.15 (4.4): flagged AND exclusive. Reporting the first alone
    # invites the reading that each screen is catching what it flags. On 938
    # perovskites radii ratio flags 48 and catches 0 of them that nothing else
    # catches; the one structure it flags and bond-valence distance does not,
    # ICSD 129898, is already EXPUNGE on anion packing. The 30-structure test
    # set says the same, and so did the earlier perovskite run: three datasets.
    # It is corroboration - independent of the bond valence parameters, which
    # is worth something - and it is not a catch.
    _flags = {_n: (per[_c] == False) for _n, _c in _screens}
    out(f"    {'screen':<24} {'flagged':>7}  {'exclusive':>9}")
    for _n, _c in _screens:
        _f = _flags[_n]
        _others = pd.Series(False, index=per.index)
        for _m, _g in _flags.items():
            if _m != _n:
                _others |= _g
        out(f"    {_n:<24} {int(_f.sum()):7d}  {int((_f & ~_others).sum()):9d}")
    out()
    out("    'exclusive' is the number a screen flags that no other screen")
    out("    flags. A screen with none is corroborating, not catching, and")
    out("    should not be the reason a structure is condemned.")
    out()
    if 'structure_pgrm_tier' in per.columns:
        out()
        out("  INTEGRITY VERDICT")
        out()
        _t = per['structure_pgrm_tier'].value_counts()
        _why = PGRM_TIER_MEANING
        for _k in reversed(PGRM_TIERS):
            if _k in _t:
                out(f"    {_k:<22}{_t[_k]:5}  ({100.0 * _t[_k] / n_all:5.1f}%)"
                    f"   {_why.get(_k, '')}")
        _ex = per[per['structure_pgrm_tier'] == 'EXPUNGE']
        if len(_ex):
            out()
            out("    Quote no bond valence result for an expunged structure.")
            out("    The number is arithmetic on impossible coordinates and is")
            out("    often a GOOD number. Reasons:")
            for _r, _n in _ex['structure_pgrm_reason'].value_counts().items():
                out(f"      {str(_r):<34}{_n:4}")
        out()

    pct = 100.0 * n_good / n_all if n_all else 0
    out(f"  Passed every test            {n_good} of {n_all}  ({pct:.0f}%)")
    out(f"  Failed at least one          {n_bad} of {n_all}  ({100-pct:.0f}%)")
    out()
    if n_bad and len(_screens) > 1:
        _nfail = sum((per[_c] == False).astype(int) for _n, _c in _screens)
        _one = int((_nfail == 1).sum())
        _multi = int((_nfail > 1).sum())
        _all3 = int((_nfail == len(_screens)).sum())
        out(f"  Of the {n_bad} flagged, {_one} fail exactly one test and {_multi} fail")
        out(f"  more than one" + (f", with {_all3} failing all {len(_screens)}." if _all3
                                  else f". None fails all {len(_screens)}."))
        out("  The tests are therefore picking up different faults rather than")
        out("  restating the same one, which is why all are reported.")
        out("")
        # v2.0.2: built from _screens rather than hard-coded. The header
        # listed three columns while the loop below computed marks for all of
        # them, so the coordination and half-lattice verdicts were calculated
        # and then dropped on the floor.
        _abbr = {'radii ratio': 'radii', 'bond-valence distance': 'BVS dist',
                 'anion-anion packing': 'anion pack', 'coordination': 'coord',
                 'half-lattice shift': 'shift'}
        _w = 11
        out('      ' + f"{'ICSD':<32}"
            + ''.join(f'{_abbr.get(_n, _n):<{_w}}' for _n, _c in _screens)
            + f"{'shortest anion-anion':<20}")
        for f in sorted(per.index[~plaus_mask]):
            short = f
            # keep the collection code, drop the dataset prefix whatever it is
            short = re.sub(r'^.*?CollCode', '', short).replace('.cif', '') or short
            marks = []
            for _n, _c in _screens:
                marks.append('FAIL' if per.loc[f, _c] == False else '  . ')
            _aa = per.loc[f, 'anion_anion_min'] if 'anion_anion_min' in per.columns else None
            _aatxt = f"{_aa:.3f} A" if _aa == _aa and _aa is not None else ""
            out('      ' + f'{short:<32}'
                + ''.join(f'{m:<{_w}}' for m in marks)
                + f'{_aatxt:<20}')
        out("")

    # ---------------------------------------------------------------- 2
    out("-" * 78)
    out("2. BOND VALENCE RESULTS")
    out("-" * 78)
    out()
    out("  The global instability index (GII) measures how far the bond valence")
    out("  sums depart from the expected valences across a whole structure.")
    out()
    out("  A word of caution on thresholds. The often-quoted figure of 0.20 v.u.")
    out("  is a rule of thumb drawn from relatively simple ordered structures.")
    out("  Families whose connectivity over-constrains the geometry - spinels")
    out("  and many perovskites among them - routinely exceed it while being")
    out("  perfectly stable, because the strain is built into the structure")
    out("  type rather than indicating an unstable compound. Read the numbers")
    out("  below against an expectation for this family, not against 0.20.")
    out()
    out(f"  {'':<34} {'all structures':>14} {'passed all tests':>16}")
    out(f"  {'':<34} {'-'*14:>14} {'-'*16:>16}")
    out(_two_column("Structures", n_all, n_good, 0))
    out(_two_column("Mean GII (v.u.)", per['gii'].mean(), good['gii'].mean()))
    out(_two_column("Median GII (v.u.)", per['gii'].median(), good['gii'].median()))
    out(_two_column("  25th percentile", per['gii'].quantile(.25), good['gii'].quantile(.25)))
    out(_two_column("  75th percentile", per['gii'].quantile(.75), good['gii'].quantile(.75)))
    out(_two_column("  minimum", per['gii'].min(), good['gii'].min()))
    out(_two_column("  maximum", per['gii'].max(), good['gii'].max()))
    if 'gii_site_averaged' in per.columns and per['gii_site_averaged'].notna().any():
        out(_two_column("Mean GII, site-averaged (v.u.)",
                        per['gii_site_averaged'].mean(), good['gii_site_averaged'].mean()))
        out(_two_column("  median", per['gii_site_averaged'].median(),
                        good['gii_site_averaged'].median()))
    if 'wagii' in per.columns:
        out(_two_column("Mean WAGII (v.u.)", per['wagii'].mean(), good['wagii'].mean()))
    if 'gii_all_sites' in per.columns and per['gii_all_sites'].notna().any():
        out(_two_column("Mean GII incl. anions (v.u.)",
                        per['gii_all_sites'].mean(), good['gii_all_sites'].mean()))
    if 'anion_bvs_mean' in per.columns:
        out(_two_column("Mean anion BVS (expect 2.00)",
                        per['anion_bvs_mean'].mean(), good['anion_bvs_mean'].mean()))

    # ---------------------------------------------------------------- 2a
    # WHICH GII TO QUOTE (new in 2.0.2)
    #
    # Eir reports one row per species per site, so a site shared by two
    # elements produces two bond valence sums at the same geometry. The
    # minority species is asked what its sum would be in a site whose size the
    # majority sets, and answers with something absurd: in ICSD 119329,
    # Nd2Zr2O7 refined with 2% anti-site mixing, the 2% Nd on the zirconium
    # site returns 9.22 v.u. against an expected 3, and that single phantom row
    # carries the same weight as the 98% it sits among. Structure GII 3.75;
    # site-averaged 1.91; the ordered members of the same family sit near 0.19.
    #
    # gii            per species. Correct for an ordered structure, and the
    #                right quantity when the question is about one species.
    # gii_site_averaged
    #                one deviation per crystallographic site, from the
    #                occupancy-weighted combination of the per-species sums.
    #                The right headline for a dataset containing disorder.
    # wagii          occupancy-weighted across sites; down-weights minority
    #                species but still reports them separately.
    #
    # The choice is made here from the measured disorder fraction rather than
    # left to the reader, and the reasoning is printed either way.
    # v2.0.2: prefer the anti-site verdict, which names the actual reason a
    # per-species GII misleads, over the raw disorder fraction. A site shared
    # by two species that appear nowhere else is a solid solution and the sums
    # are meaningful; a species that is a minority here and a majority on
    # another site is anti-site exchange, and its sum is a phantom.
    _anti = None
    if 'has_antisite_disorder' in per.columns:
        _anti = per['has_antisite_disorder'].astype(str).str.lower().eq('true')
    elif 'n_antisite_species' in per.columns:
        _anti = pd.to_numeric(per['n_antisite_species'],
                              errors='coerce').fillna(0) > 0
    if _anti is not None and _anti.any():
        _a, _b = per[_anti.values], per[~_anti.values]
        out()
        out(f"  Anti-site exchange: {int(_anti.sum())} of {n_all} structures.")
        out()
        out("  Eir reports one bond valence sum per SPECIES per site. Where a")
        out("  site is shared, the minority species is asked what its sum would")
        out("  be in a cavity the majority sizes; it answers with something")
        out("  impossible, and the per-species GII weights that phantom equally")
        out("  with the majority it sits among.")
        out()
        _cols = [c for c in ('gii', 'wagii', 'gii_site_averaged')
                 if c in per.columns]
        out(f"      {'':24}" + ''.join(f'{c:>18}' for c in _cols))
        for _lbl, _sub in ((f'with anti-site ({len(_a)})', _a),
                           (f'ordered ({len(_b)})', _b)):
            out(f"      {_lbl:24}" + ''.join(
                f"{pd.to_numeric(_sub[c], errors='coerce').median():>18.4f}"
                for c in _cols))
        out()
        if {'gii', 'wagii'} <= set(_cols) and len(_b):
            _r = (pd.to_numeric(_b['gii'], errors='coerce')
                  / pd.to_numeric(_b['wagii'], errors='coerce')).median()
            out(f"  On the structures with no shared site gii/wagii is {_r:.3f}.")
            out("  The two are the same quantity when every cation site")
            out("  carries the SAME occupancy - not merely when nothing is")
            out("  shared, and not only at full occupancy. WAGII weights each")
            out("  site by its occupancy, so unequal weights are what separate")
            out("  them, and a vacancy does that only where it leaves the")
            out("  sites unequal; with one cation site the weight cancels.")
            out("  Measured on 539 rock salts, 308 carry one occupancy across")
            out("  every cation site and gii == wagii on all 308, the 42 not")
            out("  fully occupied included; of the 231 unequal, 7 coincide.")
            out("  That is what makes the weighted form safe to quote")
            out("  throughout.")
            out()
        out("  The column gii_recommended carries the choice per structure.")
        out("  Which index to quote for the DATASET is decided once, below,")
        out("  under 'Which GII to quote'.")
        out()

    _disorder_frac = None
    if 'has_mixed_occupancy' in dfq.columns:
        _mx = dfq['has_mixed_occupancy'].astype(str).str.lower().eq('true')
        _dis_struct = dfq.assign(_m=_mx).groupby('filename')['_m'].any()
        _disorder_frac = float(_dis_struct.mean())
        _site_frac = float(_mx.mean())

    if _disorder_frac is not None:
        out()
        out("  Which GII to quote.")
        out()
        out(f"  {100 * _disorder_frac:.0f}% of structures here contain at least one site")
        out(f"  shared by two or more species ({100 * _site_frac:.0f}% of all sites).")
        out()
        if _disorder_frac >= 0.10:
            _g_all = per['gii'].median()
            _g_sa = (per['gii_site_averaged'].median()
                     if 'gii_site_averaged' in per.columns else None)
            out("  That is enough for the per-species GII above to be misleading as a")
            out("  headline figure. Eir reports one row per species per site, so a")
            out("  minority species is asked what its bond valence sum would be in a")
            out("  site whose size the majority sets. It returns something impossible,")
            out("  and it is then weighted equally with the majority it sits among.")
            out()
            if _g_sa is not None:
                out(f"      median GII, per species     {_g_all:.4f} v.u.")
                out(f"      median GII, site-averaged   {_g_sa:.4f} v.u.")
                out()
            out("  QUOTE THE SITE-AVERAGED FIGURE for this dataset, and say so.")
            out("  The per-species column remains the right one for a question")
            out("  about a particular species, and where every occupancy is 1.0")
            out("  the three indices agree.")
            out()
            out("  This is the ONLY recommendation in this report. Until v2.0.13")
            out("  the section above also carried one, naming WAGII, so two")
            out("  instructions naming different columns sat 30 lines apart on")
            out("  the same page.")
        else:
            out("  That is low enough that the per-species and site-averaged figures")
            out("  will agree closely, and the per-species GII above can be quoted")
            out("  directly. State which you used regardless: on a dataset with more")
            out("  disorder the two diverge sharply.")
        out()
        out("  Whichever is quoted, state the geometry screening alongside it. A")
        out("  bond valence sum built on an impossible bond length is not evidence")
        out("  of instability, it is evidence of a bad structure, and the two are")
        out("  not distinguishable from the number alone.")
    out()
    delta = per['gii'].mean() - good['gii'].mean()
    if abs(delta) > 0.005:
        out(f"  Excluding the {n_bad} implausible structures lowers the mean GII by")
        out(f"  {abs(delta):.4f} v.u. Quote the right-hand column, and state the")
        out("  screening, rather than reporting the unfiltered figure alone.")
        out()

    # --- ordered vs shared sites ----------------------------------------
    # One row per crystallographic SITE, using the occupancy-weighted
    # deviation. Reporting one row per species instead counts a shared site
    # twice and asks each species what its sum would be if it owned a
    # geometry set by the other, which is a counterfactual rather than a
    # measurement.
    sub_ok = dfq[dfq['filename'].isin(good_files)].copy()
    if 'site_deviation_averaged' in sub_ok.columns and 'coords' in sub_ok.columns:
        _sites = sub_ok.drop_duplicates(subset=['filename', 'coords'])
        _sites = _sites[_sites['site_deviation_averaged'].notna()].copy()
        _sites['_dev'] = _sites['site_deviation_averaged'].abs()
        out("  Deviation per crystallographic site, structures passing every test:")
        out()
        out(f"      {'site type':<34}{'sites':>8}{'mean |BVS - expected|':>24}")
        if 'n_elements_at_site' in _sites.columns:
            _ne = _sites['n_elements_at_site'].fillna(1).astype(int)
            _ordered = _sites[_ne == 1]['_dev']
            _shared = _sites[_ne >= 2]['_dev']
            out(f"      {'one element at site':<34}{len(_ordered):>8}{_ordered.mean():>24.4f}")
            out(f"      {'shared by two elements':<34}{len(_shared):>8}{_shared.mean():>24.4f}")
        else:
            _ordered = _shared = pd.Series(dtype=float)
        _fr = (_sites['valence'] - _sites['valence'].round()).abs() > 1e-6
        out(f"      {'integer assumed valence':<34}{int((~_fr).sum()):>8}"
            f"{_sites.loc[~_fr, '_dev'].mean():>24.4f}")
        out(f"      {'fractional assumed valence':<34}{int(_fr.sum()):>8}"
            f"{_sites.loc[_fr, '_dev'].mean():>24.4f}")
        out()
        if len(_ordered) and len(_shared) and _ordered.mean() > 0:
            _ratio = _shared.mean() / _ordered.mean()
            out(f"  A shared site deviates about {_ratio:.1f} times as much as an ordered")
            out("  one. That is a statement about precision, not validity: bond valence")
            out("  on a site holding two species is a less precise measurement, by a")
            out("  factor that can be quoted, and the figures above are how to quote it.")
            out()
            out("  Two things about the earlier, larger figure for this gap. Reporting")
            out("  one row per species rather than per site inflates it, because a")
            out("  minority species is asked what its sum would be in a site whose")
            out("  geometry the majority sets: a 1.6% anti-site impurity was carrying")
            out("  the same weight as the 98% it sits among. And several structures")
            out("  contributing most of the apparent gap turned out to fail a geometry")
            out("  test, so the effect was partly bad data wearing a disguise.")
            out()

    out("-" * 78)
    out("3. WHERE THE DEVIATION COMES FROM")
    out("-" * 78)
    out()
    out("  Every bond contributes to one cation sum and one anion sum, so a")
    out("  cation discrepancy that cancels at the shared oxygen is a property")
    out("  of the parameters, not of the structure. Comparing the two sides")
    out("  separates those cases.")
    out()
    out(f"  {'':<34} {'all structures':>14} {'passed all tests':>16}")
    out(f"  {'':<34} {'-'*14:>14} {'-'*16:>16}")
    _dcol = ('bvs_diagnosis_detail'
             if 'bvs_diagnosis_detail' in per.columns else 'bvs_diagnosis')
    va = per[_dcol].value_counts()
    vg = good[_dcol].value_counts()
    for k in DIAGNOSIS_ORDER_REPORT:
        if k in va.index or k in vg.index:
            out(_two_column(k, va.get(k, 0), vg.get(k, 0), 0))
    out()
    for k in DIAGNOSIS_ORDER_REPORT:
        if k in va.index and k in DIAGNOSIS_MEANING:
            out(f"    {k}")
            out(f"        {DIAGNOSIS_MEANING[k]}")
    out()

    # ---------------------------------------------------------------- 4
    out("-" * 78)
    out("4. COORDINATION QUALITY")
    out("-" * 78)
    out()
    # Half-lattice proposals, and what testing them showed.
    if 'n_sites_shift_proposed' in per.columns:
        _np = pd.to_numeric(per['n_sites_shift_proposed'],
                            errors='coerce').fillna(0)
        _ns = int((_np > 0).sum())
        if _ns:
            out(f"  {_ns} structures carry a proposed half-lattice shift: a")
            out("  cation whose coordination sphere is SPLIT, short on one side")
            out("  and long on the other, which every short-contact test passes")
            out("  because nothing is individually too short. Where the bond")
            out("  valence sum also passes, as it often does because the two")
            out("  halves cancel, only the geometry gives it away.")
            out()
            out("  Nothing is corrected. CELL 13b applies each proposal to a")
            out("  COPY and re-runs the whole analysis, so the proposal can be")
            out("  judged on what it gives rather than on what it claims.")
            out()

            # What testing them showed. Picked up from CELL 13b automatically
            # so that CELL 15 needs no argument; passing shift_results
            # explicitly overrides it.
            _sr = shift_results
            if _sr is None:
                _sr = globals().get('_shift_results')
            if _sr is not None and len(_sr):
                _sr = _sr.copy()
                if 'variant' not in _sr.columns:
                    # a run from before the variant column existed: the two
                    # hypotheses alternate in file order
                    _sr['variant'] = (_sr.groupby('filename').cumcount()
                                      .map({0: 'single_site', 1: 'all_cations'}))
                _done = _sr.dropna(subset=['gii_after'])
                out("  RESULT OF TESTING THEM")
                out()
                out("  Two hypotheses per structure: moving only the cation the")
                out("  screen named, and moving every cation by the same vector.")
                out("  The second describes a cation sublattice deposited on the")
                out("  wrong origin, which the first cannot represent.")
                out()
                _tab = pd.crosstab(_sr['variant'], _sr['verdict'])
                for _line in _tab.to_string().splitlines():
                    out('      ' + _line)
                out()
                if len(_done):
                    _best = (_done.sort_values('gii_after')
                                  .drop_duplicates('filename'))
                    _wins = _best['variant'].value_counts().to_dict()
                    out(f"  Better hypothesis per structure: {_wins}")
                    _ss = _done[_done['variant'] == 'single_site']
                    if len(_ss) and {'n_screens_failed_before',
                                     'n_screens_failed_after'} <= set(_ss.columns):
                        _b = pd.to_numeric(_ss['n_screens_failed_before'],
                                           errors='coerce').sum()
                        _a = pd.to_numeric(_ss['n_screens_failed_after'],
                                           errors='coerce').sum()
                        _clean = int((pd.to_numeric(
                            _ss['n_screens_failed_after'],
                            errors='coerce') == 0).sum())
                        out(f"  Moving the named cation alone takes screen failures")
                        out(f"  across these structures from {int(_b)} to {int(_a)},")
                        out(f"  and leaves {_clean} of {len(_ss)} passing every test.")
                    out()
                    _sup = _done[_done['verdict'].astype(str)
                                 .str.contains('supported', case=False, na=False)
                                 & ~_done['verdict'].astype(str)
                                 .str.startswith('NOT')]
                    if len(_sup):
                        _sup = _sup.assign(_r=pd.to_numeric(_sup['gii_before'],
                                                            errors='coerce')
                                           / pd.to_numeric(_sup['gii_after'],
                                                           errors='coerce'))
                        _cols = [c for c in ('icsd_code', 'chemical_formula',
                                             'shift_applied', 'gii_before',
                                             'gii_after', 'verdict')
                                 if c in _sup.columns]
                        out("  Best supported:")
                        for _line in (_sup.nlargest(min(8, len(_sup)), '_r')[_cols]
                                      .to_string(index=False).splitlines()):
                            out('      ' + _line)
                        out()
                out("  A supported shift is evidence that the deposited cation")
                out("  sits on the wrong origin. It is not a correction, and the")
                out("  deposited entry remains the data of record until the")
                out("  source says otherwise.")
                out()

    if 'cn_tie_extended' in dfq.columns:
        _tie = dfq['cn_tie_extended'].astype(str).str.lower().eq('true')
        if _tie.any():
            out(f"  Coordination numbers are the count of bonds actually summed. On")
            out(f"  {int(_tie.sum())} sites the shell boundary fell inside a set of")
            out(f"  symmetry-equivalent bonds, so every one of them was included and")
            out(f"  the reported CN is larger than the gap analysis alone would give.")
            out(f"  That is correct: the boundary is a distance, and equal bonds")
            out(f"  cannot be separated by one.")
            out()
    if 'cn_revised' in dfq.columns:
        _rev = dfq['cn_revised'].astype(str).str.lower().eq('true')
        if _rev.any():
            out(f"  On {int(_rev.sum())} sites the coordination shell from gap analysis")
            out(f"  disagreed with ECoN and was extended; see cn_gap, econ_shell and")
            out(f"  cn_revision_reason for each. Gap analysis cuts at the largest gap")
            out(f"  in the bond list, which is the shell boundary for a compact")
            out(f"  polyhedron and an internal gap for a broad one.")
            out()
    out("  The effective coordination number (ECoN, Hoppe 1979) weights each")
    out("  bond by its length. For a regular polyhedron ECoN equals the integer")
    out("  coordination number; it falls below it as the polyhedron distorts.")
    out("  A low ratio on a Jahn-Teller active ion is a chemical result, not an")
    out("  error, and distinguishes real strain from a bad structure.")
    out()
    sub = dfq[dfq['filename'].isin(good_files)]
    reg = sub['polyhedron_regular'].dropna()
    if 'bl_tier' in dfq.columns and dfq['bl_tier'].notna().any():
        _bt = pd.to_numeric(dfq['bl_tier'], errors='coerce')
        # v2.0.46: read as optional, as bl_tier is above. Since 2.0.46 the
        # batch always writes both, but an older results CSV may not.
        _bd = pd.to_numeric(dfq.get('bl_delta_mean'), errors='coerce') \
            if 'bl_delta_mean' in dfq.columns else pd.Series(dtype=float)
        _br = pd.to_numeric(dfq.get('bl_ratio_min'), errors='coerce') \
            if 'bl_ratio_min' in dfq.columns else pd.Series(dtype=float)
        out("  MEASURED BOND LENGTHS")
        out()
        out("  bl_expected_mean is the mean bond length observed for this exact")
        out("  ion configuration across Gagne's survey of refined inorganic")
        out("  structures; bl_delta_mean is this site's mean minus that, in")
        out("  angstroms, and bl_n_bonds is the sample it rests on.")
        out()
        _lab = {1: 'measured', 2: 'interpolated', 3: 'extrapolated',
                4: 'Shannon additive'}
        for _t in (1, 2, 3, 4):
            _n = int((_bt == _t).sum())
            if _n:
                out(f"      tier {_t}  {_lab[_t]:18} {_n:6}  "
                    f"({100 * _n / int(_bt.notna().sum()):.1f}%)")
        if _bd.notna().any():
            out()
            out(f"  Observed minus expected, median {_bd.median():+.4f} A "
                f"over {int(_bd.notna().sum())} sites.")
        out()
        out("  These are REPORTED, not screened. A range test - is any bond")
        out("  outside anything ever observed for this ion - was built and")
        out("  rejected: an extreme needs a large sample, Gagne's")
        out("  high-coordination entries are the small ones, and on the")
        out("  perovskites it condemned 224 sites in structures that pass")
        out("  every other test, some with GII below 0.02. Quote")
        out("  bl_delta_mean with bl_n_bonds beside it and let the reader")
        out("  weigh it.")
        out()
        if _br.notna().any():
            out(f"  bl_ratio_min, this site's shortest contact against the")
            out(f"  shortest ever observed for this ion configuration, is")
            out(f"  available on {int(_br.notna().sum())} of {len(dfq)} sites, "
                f"median {_br.median():.3f}.")
            out("  Like against like, so it carries no coordination dependence.")
            out("  Null means the tail of the reference distribution is not")
            out("  characterised, which is a fact about the reference data.")
            out()

    if len(reg):
        out(f"  Sites in plausible structures     {sites_good}")
        out(f"  Regular polyhedra                 {int(reg.sum())} of {len(reg)}")
        out(f"  Distorted polyhedra               {int((~reg.astype(bool)).sum())} of {len(reg)}")
    out()
    six = sub[sub['cn_relative'] == 6]
    if len(six):
        g = (six.groupby('element')['econ_cn_ratio']
                .agg(['count', 'mean', 'min']))
        g = g[g['count'] >= 5].sort_values('mean')
        out("  Mean ECoN/CN by element (six-coordinate sites only):")
        out()
        out(f"      {'element':<10}{'sites':>7}{'mean':>10}{'lowest':>10}")
        for el, r in g.iterrows():
            out(f"      {el:<10}{int(r['count']):>7}{r['mean']:>10.4f}{r['min']:>10.4f}")
        out()
        # v2.0.13: only sites that are actually distorted. nsmallest on the
        # whole set lists the five lowest ratios even when all of them are
        # above ECON_REGULAR_MIN, so a run of symmetry-perfect octahedra was
        # reported under the heading 'Most distorted sites' at ratios of
        # 0.999.
        _dist = six[pd.to_numeric(six['econ_cn_ratio'],
                                  errors='coerce') < ECON_REGULAR_MIN]
        worst = _dist.nsmallest(5, 'econ_cn_ratio')
        if len(worst):
            out(f"  Most distorted sites (ECoN/CN below {ECON_REGULAR_MIN}):")
            out()
            for _, r in worst.iterrows():
                # v2.0.13: was .replace('dataset_CollCode', ''), one
                # dataset's file-naming convention hard-coded into a general
                # report. Prefer the ICSD code the CSV already carries.
                fn = (str(int(r['icsd_code']))
                      if r.get('icsd_code') == r.get('icsd_code')
                      else re.sub(r'^.*CollCode|\.cif$', '',
                                  str(r['filename'])))
                out(f"      {fn:<12} {r['element']:<4} "
                    f"ECoN {r['econ']:.2f} of 6   ratio {r['econ_cn_ratio']:.3f}")
            out()

    # ---------------------------------------------------------------- 5
    out("-" * 78)
    out("5. SETTINGS USED")
    out("-" * 78)
    out()
    cfg = [c for c in dfq.columns if c.startswith('cfg_')]
    for c in sorted(cfg):
        out(f"  {c[4:]:<32} {dfq[c].iloc[0]}")
    # the two screens added after the cfg_ columns were defined
    try:
        out(f"  {'bvs_distance_fraction':<32} {IMPLAUSIBLE_BVS_DISTANCE_FRACTION}")
        out(f"  {'anion_anion_min_A':<32} {ANION_ANION_MIN}")
    except NameError:
        pass
    out()
    out("=" * 78)

    text = "\n".join(lines)
    print(text)

    if save_to:
        with open(save_to, 'w', encoding='utf-8') as f:
            f.write(text)
        print(f"\nSaved to: {save_to}")

    return text